## Basic JSONB Operations

```sql
CREATE TABLE products (
    id       BIGSERIAL PRIMARY KEY,
    name     TEXT NOT NULL,
    metadata JSONB
);

INSERT INTO products (name, metadata) VALUES
('Laptop Pro', '{"brand": "TechCo", "specs": {"ram": 16, "cpu": "M3"}, "tags": ["laptop", "pro"]}');

-- -> returns JSON type (use for nested access)
SELECT metadata -> 'brand'         AS brand_json;   -- "TechCo" (JSON string)
SELECT metadata ->> 'brand'        AS brand_text;   -- TechCo (text)
SELECT metadata -> 'specs' ->> 'ram' AS ram;         -- 16 (text)
SELECT metadata #>> '{specs,cpu}'  AS cpu;           -- M3 (path operator)

-- Filter by JSON content
WHERE metadata @> '{"brand": "TechCo"}';  -- containment
WHERE metadata ? 'brand';                 -- key exists
WHERE metadata ->> 'brand' = 'TechCo';    -- equality on extracted text
WHERE (metadata ->> 'specs')::jsonb ->> 'ram' = '16';
```

## Indexing JSONB

```sql
-- GIN index: covers ALL keys — good for @> and ? queries
CREATE INDEX idx_product_meta ON products USING GIN (metadata);

-- Expression index: for a specific frequently-queried key
CREATE INDEX idx_product_brand
    ON products ((metadata ->> 'brand'));
-- Faster for: WHERE metadata ->> 'brand' = 'TechCo'
```

## Update Specific Keys

```sql
-- Update nested key without replacing entire document
UPDATE products
SET metadata = jsonb_set(
    metadata,
    '{specs,ram}',   -- path to key
    '32',            -- new value (must be valid JSON)
    true             -- create if not exists
)
WHERE id = 1;

-- Add a new key
UPDATE products
SET metadata = metadata || '{"color": "silver"}'::jsonb
WHERE id = 1;

-- Remove a key
UPDATE products SET metadata = metadata - 'color' WHERE id = 1;
```

